import{_ as e,o as a,c as d,a2 as o}from"./chunks/framework.DTdEDYjJ.js";const m=JSON.parse('{"title":"官方托管","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/hosted.md","filePath":"deployment/hosted.md"}'),r={name:"deployment/hosted.md"};function l(n,t,h,i,p,s){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="官方托管" tabindex="-1">官方托管 <a class="header-anchor" href="#官方托管" aria-label="Permalink to &quot;官方托管&quot;">​</a></h1><p><strong>规划中。</strong> 当前没有官方托管购买入口、统一账号服务、托管套餐或可用性 SLA。此页说明拟提供的服务形态与开源部署之间的关系。</p><h2 id="用户获得什么" tabindex="-1">用户获得什么 <a class="header-anchor" href="#用户获得什么" aria-label="Permalink to &quot;用户获得什么&quot;">​</a></h2><p>官方可以提供维护好的 OpenBot 运行环境，包含服务器配置、Node 安装、浏览器隔离、版本升级、监控、备份与故障恢复。用户继续选择自己的模型与已适配 Harness。</p><table tabindex="0"><thead><tr><th>部分</th><th>官方托管的拟议职责</th><th>用户保留的选择</th></tr></thead><tbody><tr><td>计算资源</td><td>配置与维护执行节点</td><td>自建服务器、个人设备或官方环境</td></tr><tr><td>模型连接</td><td>提供受支持的配置入口</td><td>自己的服务商、模型与 API 凭据</td></tr><tr><td>Harness</td><td>分发和验证薄 Adapter</td><td>为 Bot 选择已支持的执行框架</td></tr><tr><td>数据与权限</td><td>维护隔离、备份与访问控制</td><td>授权设备、查看记录、撤销访问、迁移数据</td></tr><tr><td>服务支持</td><td>升级、监控与运行维护</td><td>继续使用开源自托管版本</td></tr></tbody></table><p>初期可以选用阿里云作为算力供应商，后续也可以替换其他云。用户选择模型服务不必与服务器供应商一致。</p><h2 id="自带模型凭据" tabindex="-1">自带模型凭据 <a class="header-anchor" href="#自带模型凭据" aria-label="Permalink to &quot;自带模型凭据&quot;">​</a></h2><p>自带凭据通常称为 BYOK。OpenBot 已有按 Bot 选择命名 API 连接与模型的基础；官方托管仍需额外完成服务端凭据隔离、授权、撤销与数据迁移验收。</p><p>模型调用可能直接产生模型服务商费用，计算资源也有自己的成本。未来产品需要分别说明资源费用、服务费用与模型用量；目前没有已公布的套餐或价格。</p><h2 id="官方服务与自托管后台" tabindex="-1">官方服务与自托管后台 <a class="header-anchor" href="#官方服务与自托管后台" aria-label="Permalink to &quot;官方服务与自托管后台&quot;">​</a></h2><p>Hub 和 Node 可以由用户放在同一台自有服务器。用户通过自己的 HTTPS 地址登录与配对，不要求注册官方账号。</p><p>官方以后可提供可选的账号、节点地址目录与连接服务，改善新设备发现体验。已保存 Hub 地址的客户端应能继续直连自己的服务；官方目录故障不应阻止已有自托管部署工作。</p><p>如果连接经过官方中转，哪些数据经过中转、如何加密、保留多久，都需要在实现和服务说明中明确。目前没有已经验收的中转或端到端加密实现。</p><h2 id="上线前的最小闭环" tabindex="-1">上线前的最小闭环 <a class="header-anchor" href="#上线前的最小闭环" aria-label="Permalink to &quot;上线前的最小闭环&quot;">​</a></h2><ul><li>同一账号的第二设备能发现获授权节点，未授权设备被拒绝。</li><li>每设备独立凭据，撤销后控制会话、待批项和旧输入同时失效。</li><li>用户能导出并恢复自己的 Bot、任务与必要运行资料。</li><li>节点故障后任务状态准确，不自动重复副作用。</li><li>模型用量与资源收费可分别核对，未知费用不估造。</li></ul><p>现在已有服务器，可直接使用<a href="/openbot/deployment/self-host.html">Linux Node 部署</a>，并按<a href="/openbot/deployment/network.html">连接与网络</a>建立受保护的连接。</p>',16)])])}const _=e(r,[["render",l]]);export{m as __pageData,_ as default};
